<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Sorting Visualizer</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0d1117;
      --panel: #161b22;
      --border: #30363d;
      --text: #e6edf3;
      --muted: #8b949e;
      --accent: #58a6ff;
      --accent-2: #bc8cff;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      padding: 28px;
      display: flex;
      justify-content: center;
      align-items: center;
      font-family: system-ui, sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, #172033 0, transparent 42%),
        var(--bg);
    }

    .app {
      width: min(1000px, 100%);
      padding: 28px;
      border: 1px solid var(--border);
      border-radius: 18px;
      background: rgba(22, 27, 34, .94);
      box-shadow: 0 24px 70px rgba(0, 0, 0, .35);
    }

    header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 18px;
      margin-bottom: 26px;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.5rem, 4vw, 2.2rem);
      letter-spacing: -.04em;
    }

    .status {
      color: var(--muted);
      font-size: .9rem;
    }

    #bars {
      height: 380px;
      display: flex;
      align-items: end;
      gap: 5px;
      padding: 20px 14px 14px;
      border: 1px solid var(--border);
      border-radius: 12px;
      background: #0b0f14;
      overflow: hidden;
    }

    .bar {
      flex: 1 1 0;
      min-width: 3px;
      border-radius: 5px 5px 1px 1px;
      background: linear-gradient(180deg, var(--accent-2), var(--accent));
      box-shadow: 0 0 12px rgba(88, 166, 255, .16);
      transition: height .12s ease, background .12s ease;
    }

    .bar.active {
      background: linear-gradient(180deg, #ffd866, #f0883e);
      box-shadow: 0 0 18px rgba(240, 136, 62, .42);
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 22px;
    }

    button {
      border: 1px solid var(--border);
      border-radius: 9px;
      padding: 10px 18px;
      color: var(--text);
      background: #21262d;
      font: inherit;
      cursor: pointer;
      transition: background .15s, transform .15s;
    }

    button:hover {
      background: #30363d;
      transform: translateY(-1px);
    }

    button.primary {
      border-color: #388bfd;
      background: #1f6feb;
    }

    button.primary:hover { background: #388bfd; }
    button:disabled { opacity: .55; cursor: not-allowed; transform: none; }
  </style>
</head>
<body>
  <main class="app">
    <header>
      <h1>Sorting Visualizer</h1>
      <div class="status" id="status">Ready to sort</div>
    </header>

    <div id="bars" aria-label="Array bars"></div>

    <div class="controls">
      <button id="sort" class="primary">Sort</button>
      <button id="shuffle">Shuffle</button>
      <button id="reset">Reset</button>
    </div>
  </main>

  <script>
    (function () {
      const bars = document.getElementById("bars");
      const status = document.getElementById("status");
      const sortButton = document.getElementById("sort");
      const shuffleButton = document.getElementById("shuffle");
      const resetButton = document.getElementById("reset");

      const original = [42, 76, 18, 93, 35, 61, 8, 54, 87, 27, 69, 14, 48, 100, 31];
      let values = original.slice();
      let i = 1;
      let j = 1;
      let complete = false;
      let timer = null;
      let active = [];

      function isSorted() {
        for (let k = 1; k < values.length; k++) {
          if (values[k - 1] > values[k]) return false;
        }
        return true;
      }

      function draw() {
        bars.replaceChildren();
        const max = values.length ? Math.max(...values, 1) : 1;

        values.forEach((value, index) => {
          const bar = document.createElement("div");
          bar.className = "bar" + (active.includes(index) ? " active" : "");
          bar.style.height = (Math.max(0, value) / max * 100) + "%";
          bar.title = String(value);
          bars.appendChild(bar);
        });
      }

      function resetAlgorithm() {
        i = 1;
        j = 1;
        complete = values.length < 2 || isSorted();
        active = [];
      }

      function setArray(input) {
        stopAnimation();
        values = Array.from(input, Number);
        resetAlgorithm();
        draw();
        status.textContent = complete ? "Already sorted" : "Ready to sort";
      }

      function sortStep() {
        if (complete) return true;

        active = [];
        if (i >= values.length) {
          complete = true;
          draw();
          return true;
        }

        active = [j, j - 1];

        if (j > 0 && values[j] < values[j - 1]) {
          const temp = values[j];
          values[j] = values[j - 1];
          values[j - 1] = temp;
          j--;
        } else {
          i++;
          j = i;
        }

        complete = isSorted();
        draw();
        return complete;
      }

      function stopAnimation() {
        if (timer !== null) {
          clearInterval(timer);
          timer = null;
        }
        sortButton.disabled = false;
        shuffleButton.disabled = false;
        resetButton.disabled = false;
      }

      function animateSort() {
        if (complete) return;
        stopAnimation();
        sortButton.disabled = true;
        shuffleButton.disabled = true;
        resetButton.disabled = true;
        status.textContent = "Sorting…";

        timer = setInterval(function () {
          if (sortStep()) {
            stopAnimation();
            status.textContent = "Sorted ascending";
          }
        }, 55);
      }

      function shuffle() {
        stopAnimation();
        for (let k = values.length - 1; k > 0; k--) {
          const r = Math.floor(Math.random() * (k + 1));
          const temp = values[k];
          values[k] = values[r];
          values[r] = temp;
        }
        resetAlgorithm();
        draw();
        status.textContent = "Array shuffled";
      }

      sortButton.addEventListener("click", animateSort);
      shuffleButton.addEventListener("click", shuffle);
      resetButton.addEventListener("click", function () {
        setArray(original);
      });

      window.viz = {
        array: function () {
          return values.slice();
        },
        setArray: setArray,
        sortStep: sortStep,
        sorted: isSorted
      };

      draw();
    })();
  </script>
</body>
</html>
